-- =====================================================================
-- Aikido Shinjukai Admin System: full database reset (schema + sample data)
-- Target: PostgreSQL 15+ (Supabase). Run the whole file in the Supabase SQL Editor.
--
-- Running this file DROPS the public schema and rebuilds it, so all existing
-- data is deleted. Only use it to reset the database.
--
-- Conventions
--  * Primary keys are UUIDs generated by the database.
--  * Money is stored as integer cents (amount_cents), currency defaults to SGD.
--  * Times of day are minutes from midnight (19:30 = 1170).
--  * Weekday in class and availability tables: 0 = Monday ... 6 = Sunday.
--  * Class duration = end_minute - start_minute (classes are 60 minutes).
--  * Payment references: METHOD-SESSIONS-YYYYMMDD-NNNNN (see migration 004).
-- =====================================================================

DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
GRANT USAGE ON SCHEMA public TO postgres, anon, authenticated, service_role;
GRANT ALL ON SCHEMA public TO postgres, service_role;

-- Enums
CREATE TYPE "document_type" AS ENUM ('WAIVER', 'FORM', 'CERTIFICATE', 'OTHER');
CREATE TYPE "grading_outcome" AS ENUM ('PASS', 'FAIL', 'GRADED', 'NOT_GRADED');
CREATE TYPE "grading_type" AS ENUM ('MASS', 'PRIVATE');
CREATE TYPE "invoice_status" AS ENUM ('UNPAID', 'PARTIALLY_PAID', 'PAID', 'VOID');
CREATE TYPE "notification_channel" AS ENUM ('EMAIL', 'PUSH');
CREATE TYPE "notification_status" AS ENUM ('PENDING', 'SENT', 'FAILED');
CREATE TYPE "notification_type" AS ENUM ('GRADING_NOTICE', 'PROMOTION_CONGRATS', 'PAYMENT_REMINDER', 'OVERDUE_NOTICE', 'RECEIPT', 'OTHER');
CREATE TYPE "payment_channel" AS ENUM ('STRIPE', 'WHATSAPP', 'EMAIL', 'CASH', 'BANK_TRANSFER', 'OTHER');
CREATE TYPE "payment_status" AS ENUM ('PENDING', 'COMPLETED', 'FAILED');
CREATE TYPE "proof_status" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "session_status" AS ENUM ('SCHEDULED', 'COMPLETED', 'CANCELLED');
CREATE TYPE "user_role" AS ENUM ('ADMIN', 'STUDENT');

-- Sequences
CREATE SEQUENCE IF NOT EXISTS "invoice_number_seq";
CREATE SEQUENCE IF NOT EXISTS "payment_reference_counter_seq";

-- Functions
CREATE OR REPLACE FUNCTION public.assign_payment_reference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  method_code  text;
  sessions     integer;
  session_code text;
BEGIN
  method_code := CASE NEW.channel::text
    WHEN 'BANK_TRANSFER' THEN 'BT'
    WHEN 'CASH'          THEN 'C'
    WHEN 'STRIPE'        THEN 'ST'
    WHEN 'WHATSAPP'      THEN 'WA'
    WHEN 'EMAIL'         THEN 'EM'
    ELSE                      'OT'
  END;

  -- Every payment is package-backed, so the session count always comes from its package.
  SELECT sessions_total INTO sessions FROM packages WHERE id = NEW.package_id;
  IF sessions IS NULL THEN
    RAISE EXCEPTION 'A payment must reference an existing package (package_id %)', NEW.package_id;
  END IF;
  session_code := sessions::text || 'S';

  NEW.reference := method_code || '-' || session_code || '-'
    || to_char(NEW.paid_at AT TIME ZONE 'Asia/Singapore', 'YYYYMMDD') || '-'
    || lpad(nextval('payment_reference_counter_seq')::text, 5, '0');
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$;

