-- Indexes
CREATE INDEX idx_attendance_package ON attendance USING btree (student_package_id);
CREATE INDEX idx_audit_created ON audit_log USING btree (created_at);
CREATE INDEX idx_audit_entity ON audit_log USING btree (entity_type, entity_id);
CREATE UNIQUE INDEX uq_centres_single_hq ON centres USING btree (is_hq) WHERE is_hq;
CREATE INDEX idx_class_templates_centre ON class_templates USING btree (centre_id, weekday);
CREATE INDEX idx_class_templates_instructor ON class_templates USING btree (instructor_id);
CREATE INDEX idx_documents_created ON documents USING btree (created_at);
CREATE INDEX idx_documents_student_type ON documents USING btree (student_id, type);
